// Fictional demo catalogue for "Demo Boutique". All products, names and prices are invented.

// Jewellery product images are generated by scripts/generate-assets.mjs (no third-party imagery).
import { lchToHex } from "./color";

export type Undertone = "warm" | "cool" | "neutral";
export type Metal = "gold" | "silver" | "rose-gold";

interface BaseProduct {
  id: string;
  name: string;
  price: number; // GBP
  blurb: string;
}

export interface Foundation extends BaseProduct {
  category: "foundation";
  hex: string;
  undertone: Undertone;
}

export interface Lipstick extends BaseProduct {
  category: "lipstick";
  hex: string;
  undertone: Undertone;
  texture: "matte" | "satin" | "gloss";
}

export interface Blush extends BaseProduct {
  category: "blush";
  hex: string;
  undertone: Undertone;
  texture: "matte" | "satin" | "shimmer";
}

export interface Jewellery extends BaseProduct {
  category: "earrings" | "necklace";
  metal: Metal;
  image: string; // served from /products, also uploaded to YouCam as the VTO reference image
}

export type Product = Foundation | Lipstick | Blush | Jewellery;

// Foundation shades are defined in CIE LCh space so that depth (L*) and undertone (hue angle)
// are explicit and consistent with the classifier in profile.ts:
//   cool = pinker hue (46 deg), neutral = 57 deg, warm = yellower/golden (68 deg).
const DEPTHS: { code: string; name: string; L: number; C: number }[] = [
  { code: "1", name: "Porcelain", L: 86, C: 16 },
  { code: "2", name: "Ivory", L: 78, C: 22 },
  { code: "3", name: "Sand", L: 68, C: 27 },
  { code: "4", name: "Caramel", L: 57, C: 30 },
  { code: "5", name: "Mocha", L: 45, C: 29 },
  { code: "6", name: "Espresso", L: 32, C: 23 },
];
const UNDERTONE_HUE: Record<Undertone, number> = { cool: 46, neutral: 57, warm: 68 };
const UNDERTONE_CODE: Record<Undertone, string> = { cool: "C", neutral: "N", warm: "W" };

export const FOUNDATIONS: Foundation[] = DEPTHS.flatMap((d) =>
  (["cool", "neutral", "warm"] as Undertone[]).map((u) => ({
    id: `F${d.code}${UNDERTONE_CODE[u]}`,
    name: `Second Skin Serum Foundation - ${d.code}${UNDERTONE_CODE[u]} ${d.name}`,
    hex: lchToHex(d.L, d.C, UNDERTONE_HUE[u]),
    undertone: u,
    price: 32,
    category: "foundation" as const,
    blurb: "Buildable serum foundation. Finish and coverage are tuned to your skin scan in try-on.",
  })),
);

const l = (id: string, name: string, hex: string, undertone: Undertone, texture: Lipstick["texture"]): Lipstick => ({
  id,
  name: `Velvet Verse Lipstick - ${name}`,
  hex,
  undertone,
  texture,
  price: 24,
  category: "lipstick",
  blurb: `${texture[0].toUpperCase()}${texture.slice(1)} finish.`,
});

export const LIPSTICKS: Lipstick[] = [
  l("L01", "Brick Velvet", "#9e3b2a", "warm", "matte"),
  l("L02", "Coral Crush", "#e0614a", "warm", "satin"),
  l("L03", "Terracotta", "#b4553c", "warm", "satin"),
  l("L04", "Berry Bloom", "#8e2448", "cool", "matte"),
  l("L05", "Blue Red", "#b0162d", "cool", "satin"),
  l("L06", "Mauve Muse", "#a8607a", "cool", "satin"),
  l("L07", "Rosewood", "#a2525a", "neutral", "satin"),
  l("L08", "Nude Petal", "#c98a7d", "neutral", "gloss"),
  l("L09", "Plum Noir", "#5e1f3a", "cool", "matte"),
  l("L10", "Golden Nude", "#b97858", "warm", "gloss"),
  l("L11", "Cherry Gloss", "#c0243b", "neutral", "gloss"),
  l("L12", "Cinnamon", "#8d4a33", "warm", "matte"),
];

const b = (id: string, name: string, hex: string, undertone: Undertone, texture: Blush["texture"]): Blush => ({
  id,
  name: `Cloud Cheek Blush - ${name}`,
  hex,
  undertone,
  texture,
  price: 22,
  category: "blush",
  blurb: `${texture[0].toUpperCase()}${texture.slice(1)} powder-cream blush.`,
});

export const BLUSHES: Blush[] = [
  b("B01", "Peach", "#f19a7b", "warm", "matte"),
  b("B02", "Apricot Glow", "#e88a5c", "warm", "satin"),
  b("B03", "Pink Petal", "#ef8fa5", "cool", "matte"),
  b("B04", "Berry Flush", "#c75a7a", "cool", "satin"),
  b("B05", "Rose", "#d97b80", "neutral", "satin"),
  b("B06", "Terracotta Sun", "#b8603f", "warm", "shimmer"),
  b("B07", "Plum Dusk", "#9c4a68", "cool", "matte"),
  b("B08", "Mauve", "#c27b8e", "neutral", "matte"),
];

export const JEWELLERY: Jewellery[] = [
  { id: "E01", category: "earrings", metal: "gold", name: "Halo Hoop Earrings - 18k Gold Vermeil", price: 65, image: "/products/earring-gold-hoop.png", blurb: "Polished 25mm hoops." },
  { id: "E02", category: "earrings", metal: "silver", name: "Droplet Earrings - Sterling Silver", price: 55, image: "/products/earring-silver-drop.png", blurb: "Teardrop drops with a high-shine finish." },
  { id: "E03", category: "earrings", metal: "rose-gold", name: "Petal Stud Earrings - Rose Gold", price: 49, image: "/products/earring-rosegold-stud.png", blurb: "Everyday studs with a soft blush tone." },
  { id: "N01", category: "necklace", metal: "gold", name: "Sunray Pendant Necklace - 18k Gold Vermeil", price: 89, image: "/products/necklace-gold-pendant.png", blurb: "Fine chain with a round pendant." },
  { id: "N02", category: "necklace", metal: "silver", name: "Moonline Chain Necklace - Sterling Silver", price: 75, image: "/products/necklace-silver-chain.png", blurb: "Delicate cable chain with a bar drop." },
  { id: "N03", category: "necklace", metal: "rose-gold", name: "Blush Heart Necklace - Rose Gold", price: 79, image: "/products/necklace-rosegold-heart.png", blurb: "Minimal heart pendant." },
];

export const ALL_PRODUCTS: Product[] = [...FOUNDATIONS, ...LIPSTICKS, ...BLUSHES, ...JEWELLERY];

export function findProduct(id: string | undefined | null): Product | undefined {
  if (!id) return undefined;
  return ALL_PRODUCTS.find((p) => p.id === id);
}
